                  t3 t4 t5 t6)
             F (Z_to_bv 64 0xfd6d8) fc None m' (seg_rom asegs)
    /\ munch [(usp - 2416, usp)] m m' /\ wmono asegs m m' /\ mem_inv asegs m' /\ stk asegs m' lo (usp + -96)
    /\ rw_cells asegs m' (usp + -96) [C8 (Z_to_bv 64 ap); C8 (Z_to_bv 64 ap); C8 s2; C8 (Z_to_bv 64 ap); C8 (Z_to_bv 64 0x15265);
